        "when": "the query result is returned",
        "then": "password hashes, API keys, and secrets are not included"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Users can export unlimited rows of production data",
      "scenario": "A business user runs SELECT * FROM users and exports millions of customer records with PII to their local machine, creating a massive data breach surface with no detection or prevention.",
      "component": "Query Executor",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        {
          "quote": "business users can build their own reports"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-770"],
      "plainLanguage": "Users can download the entire database to their laptop because there's no limit on how many rows they export.",
