      "stride": "DenialOfService",
      "title": "Expensive queries can exhaust database resources",
      "scenario": "A business user runs SELECT * FROM large_table JOIN other_table with no WHERE clause, consuming all CPU and memory on the replica, making the dashboard unresponsive for everyone.",
      "component": "Query Executor",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "free SQL editor"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-400"],
      "plainLanguage": "A poorly written query can crash the system because there's no timeout or resource limit.",
      "requirement": {
        "title": "Implement query timeout and resource limits",
        "given": "a user executes a query",
        "when": "it runs for more than a threshold time or uses too much memory",
        "then": "the query is terminated automatically"
      }
    },
    {
      "stride": "Tampering",
      "title": "Users can execute write operations on the replica",
      "scenario": "A business user runs UPDATE users SET role='admin' or DROP TABLE sensitive_data, corrupting the replica or causing replication to break and cascading to production.",
      "component": "SQL Editor",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "free SQL editor"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-284"],
      "plainLanguage": "Users can delete or modify data because the database connection isn't restricted to read-only.",
      "requirement": {
        "title": "Use read-only database connection",
        "given": "the SQL editor connects to the database",
        "when": "a user attempts a write operation",
        "then": "the query is rejected with a permissions error"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No audit log of who ran which query",
      "scenario": "A business user exports customer PII for unauthorized purposes, later denies the action, and there is no record of who executed the query or when, preventing incident response.",
      "component": "Audit Logger",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "business users can build their own reports"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Users can deny running sensitive queries because the system doesn't record who did what.",
      "requirement": {
        "title": "Log all executed queries with user identity and timestamp",
        "given": "a user submits a query",
        "when": "the query is executed",
        "then": "the full query text, user ID, and timestamp are logged"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Authentication mechanism not specified",
      "scenario": "The design does not describe how users authenticate, so an attacker could potentially access the dashboard through weak credentials, session hijacking, or missing access controls.",
      "component": "Authentication Service",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Business users get a reporting dashboard"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-306"],
      "plainLanguage": "Attackers might access the dashboard without proper login because the design doesn't mention how users prove who they are.",
      "requirement": {
        "title": "Require strong authentication for dashboard access",
        "given": "a user attempts to access the dashboard",
        "when": "they have not authenticated",
        "then": "they are redirected to a login page with MFA"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "SQL injection in the query editor interface",
      "scenario": "If the editor itself constructs queries by concatenating user input, an attacker could inject SQL to bypass filters, access admin functions, or execute stored procedures that escalate privileges.",
      "component": "SQL Editor UI",
      "likelihood": 2,
      "impact": 5,
      "evidence": [
        {
          "quote": "free SQL editor"
        }
      ],
      "asvs": ["V5.3.4"],
      "cwe": ["CWE-89"],
      "plainLanguage": "An attacker could take over the database by typing special SQL characters that break out of the query.",
      "requirement": {
        "title": "Validate and sanitize all user input to the SQL editor",
        "given": "a user types into the SQL editor",
        "when": "the query is submitted",
        "then": "dangerous characters and commands are detected and blocked"
      }
    }
  ]
